window.kbPageData["views/entry/k-728a09fe8b200e76"] = {"key":"entry/k-728a09fe8b200e76","state":{"route":"entry/k-728a09fe8b200e76"},"node":{"id":"k-728a09fe8b200e76","mode":"k","title":"菱形、平行四边形与四边形的包含关系","type":"概念与词义","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2025 副省级 行测#100"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"菱形是四条边都相等的平行四边形，平行四边形是两组对边分别平行的四边形。因此，菱形、平行四边形、四边形的范围依次扩大。","review":{"definition":"菱形是四条边都相等的平行四边形，平行四边形是两组对边分别平行的四边形。因此，菱形、平行四边形、四边形的范围依次扩大。","explanation":"本题选A。A项先分别说明平行四边形和菱形都属于四边形，再给出菱形属于平行四边形的结论，与题干中乔木、水杉、植物的示例句式一致。菱形属于平行四边形有几何定义作依据，仅凭两者同属四边形无法推出这一结论。B项则直接利用已给出的两级包含关系推出蝴蝶属于动物，采用的是包含关系的传递。","references":[],"evidence":"所有的平行四边形都是四边形，所有的菱形都是四边形，所以，所有的菱形都是平行四边形","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 副省级 行测#100":{"paper":"国考 2025 副省级 行测","n":100,"mod":"判断推理","src":["ffe12c35a46d4df574ec.pdf",20],"asrc":["ff0b352b44d417525086.pdf",31],"card":"e3b75e936f35cd2e2793668d","links":[{"id":"k-728a09fe8b200e76","role":"解题依据","why":"菱形属于平行四边形，平行四边形属于四边形，因此三个概念满足逐级包含条件。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-728a09fe8b200e76":[["国考 2025 副省级 行测#100"]]}};
